def transform(grid):
    h,w=len(grid),len(grid[0])
    sy=next((r for r in range(h) if all(x==5 for x in grid[r])),h)
    sx=next((c for c in range(w) if all(grid[r][c]==5 for r in range(sy))),w)
    pat=[row[:sx] for row in grid[:sy]]
    colors={x for row in pat for x in row if x not in (0,5,7)}
    color=next(iter(colors)) if colors else 5
    out=[[7]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if r%(sy+1)<sy and c%(sx+1)<sx:
                v=pat[r%(sy+1)][c%(sx+1)]
                if (c//(sx+1))%2 and v==color: v=5
                out[r][c]=v
    return out
